window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[344]={"id":"344","numero":344,"titre":"HTA gravidique et pré-éclampsie","objectifs":[{"id":"344-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la pré-éclampsie","contenu":"<p>La <span class=\"kw-def\"><strong>pré-éclampsie (PE)</strong></span> se définit par l'<span class=\"kw-def\">association, à partir de ≥ 20 SA</span>, d'une <span class=\"kw-etio\">HTA</span> et d'une <span class=\"kw-bio\">protéinurie</span> chez une femme jusque-là normotendue. La <span class=\"kw-bio\">protéinurie</span> est de type glomérulaire ; <strong>l'<span class=\"kw-bio\">albuminurie</span> ne fait pas partie de la définition</strong>.</p>\n      <div class=\"callout callout-danger\">\n        <strong>Définition — les 2 critères (à partir de <span class=\"kw-chiffre\">≥ 20</span> SA)</strong>\n        <ul>\n          <li><span class=\"kw-clinique\">HTA</span> : PA <span class=\"kw-chiffre\">&gt; 140/90 mmHg</span> à <span class=\"kw-chiffre\">2 reprises</span></li>\n          <li><span class=\"kw-bio\">Protéinurie</span> : <span class=\"kw-chiffre\">&gt; 0,3 g/24 h</span> <em>ou</em> <span class=\"kw-chiffre\">&gt; 30 mg/mmol</span> (ratio P/C) <em>ou</em> <span class=\"kw-chiffre\">≥ 2 croix à la BU</span></li>\n        </ul>\n      </div>\n      <p><strong>Deux formes particulières</strong></p>\n      <ul>\n        <li><span class=\"kw-def\">PE précoce</span> : survenant <span class=\"kw-chiffre\">avant 32 SA</span></li>\n        <li><span class=\"kw-def\">PE surajoutée</span> : survenant chez une patiente porteuse d'une <span class=\"kw-etio\">HTA chronique</span> préexistante</li>\n      </ul>\n      <p><strong>Définir l'<span class=\"kw-etio\">HTA</span> au cours de la <span class=\"kw-ci\">grossesse</span></strong></p>\n      <table >\n        <thead><tr><th>Niveau</th><th>Chiffres tensionnels</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>HTA</strong></span></td><td>PAS <span class=\"kw-chiffre\">≥ 140</span> et/ou PAD <span class=\"kw-chiffre\">≥ 90</span> mmHg à <span class=\"kw-chiffre\">≥ 2 reprises</span></td></tr>\n          <tr><td><span class=\"kw-etio\">HTA</span> modérée</td><td>PAS <span class=\"kw-chiffre\">140-159</span> · PAD <span class=\"kw-chiffre\">90-109</span> mmHg → éliminer un effet blouse blanche (AMT, <span class=\"kw-imagerie\">MAPA</span>)</td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>HTA sévère</strong></span></td><td>PAS <span class=\"kw-chiffre\">≥ 160</span> <strong>et/ou</strong> PAD <span class=\"kw-chiffre\">≥ 110</span> mmHg</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Ne pas confondre avec les diagnostics voisins</strong></p>\n      <div class=\"callout callout-info\">\n        <ul>\n          <li><span class=\"kw-def\">HTA gravidique</span> : <span class=\"kw-etio\">HTA</span> apparue <span class=\"kw-chiffre\">après 20 SA</span> chez une femme normotendue, <strong>sans <span class=\"kw-bio\">protéinurie</span></strong>, disparaissant <span class=\"kw-chiffre\">avant la fin de la 6ᵉ semaine</span> du post-partum.</li>\n          <li><span class=\"kw-etio\">HTA chronique</span> : <span class=\"kw-etio\">HTA</span> antérieure à la <span class=\"kw-ci\">grossesse</span> (parfois méconnue) — à évoquer si HTA <span class=\"kw-chiffre\">découverte avant 20 SA</span> ou <span class=\"kw-chiffre\">persistant &gt; 6 semaines</span> après l'accouchement.</li>\n        </ul>\n      </div>\n      <p><strong>Conditions de mesure de la PA</strong> (circonstances de découverte)</p>\n      <ul>\n        <li>Au <span class=\"kw-clinique\">repos</span> (<span class=\"kw-chiffre\">≥ 5 min</span>), à distance de l'examen gynécologique, brassard adapté à la morphologie</li>\n        <li>En <span class=\"kw-clinique\">décubitus latéral gauche</span> ou <span class=\"kw-clinique\">semi-assise</span> (pour éviter un syndrome cave)</li>\n        <li><span class=\"kw-def\">Dépistage</span> à <strong>chaque consultation prénatale</strong> : <span class=\"kw-clinique\">PA + bandelette urinaire</span></li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span class=\"kw-ci\">Grossesse</span> normale · 24 — Complications de la grossesse · 224 — <span class=\"kw-etio\">HTA</span> de l'adulte</em></p>","frequence":2},{"id":"344-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître l'évolution naturelle et les complications maternelles et fœtales associées à la pré-éclampsie","contenu":"<p>La pré-éclampsie est une <span class=\"kw-def\">dysfonction endothéliale systémique maternelle d'origine placentaire</span> — une microangiopathie <span class=\"kw-etio\">thrombotique</span> spécifique de la <span class=\"kw-ci\">grossesse</span>. Elle découle d'un <span class=\"kw-clinique\">trouble précoce de la placentation</span> responsable d'une <span class=\"kw-alerte\">insuffisance placentaire</span>.</p>\n      <p><strong>Cascade physiopathologique</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">1ᵉʳ trimestre</span> : défaut d'invasion trophoblastique des <span class=\"kw-bio\">artères spiralées</span>, qui restent étroites et sensibles aux substances vasopressives</li>\n        <li><span class=\"kw-clinique\">2ᵉ-3ᵉ trimestre</span> : hypoperfusion et <span class=\"kw-alerte\">ischémie placentaire</span> → relargage de facteurs anti-angiogéniques (<span class=\"kw-bio\">sFlt1</span> qui capte le VEGF) et pro-inflammatoires</li>\n        <li>Conséquence : <span class=\"kw-alerte\">dysfonction endothéliale systémique</span> → <span class=\"kw-etio\">HTA</span>, <span class=\"kw-bio\">protéinurie</span>, hypovolémie efficace, état procoagulant</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong><span class=\"kw-clinique\">Évolution</span> naturelle.</strong> La pré-éclampsie <span class=\"kw-alerte\">évolue tant que la grossesse est en place</span>. Le <strong>seul traitement curatif est l'arrêt de la <span class=\"kw-ci\">grossesse</span> et la délivrance du placenta</strong> — mais la pathologie peut encore évoluer dans le <span class=\"kw-chiffre\">post-partum immédiat</span> (manifestations possibles jusqu'à <span class=\"kw-chiffre\">6 semaines</span> après l'accouchement).</div>\n      <p><strong>Complications maternelles</strong></p>\n      <ul>\n        <li><span class=\"kw-alerte\">HTA sévère non contrôlée</span>, rétinopathie ± décollement de rétine exsudatif, <span class=\"kw-alerte\">hémorragie cérébro-méningée</span></li>\n        <li>Crise d'<span class=\"kw-alerte\">éclampsie</span></li>\n        <li><span class=\"kw-alerte\">HELLP syndrome</span></li>\n        <li><span class=\"kw-alerte\">CIVD</span></li>\n        <li><span class=\"kw-alerte\">OAP</span> (surtout si IRA, <span class=\"kw-etio\">HTA</span> sévère ou cardiopathie sous-jacente)</li>\n        <li><span class=\"kw-alerte\">Insuffisance rénale aiguë</span> (parfois sévère, dialyse, <span class=\"kw-clinique\">nécrose</span> corticale)</li>\n        <li><span class=\"kw-alerte\">Hématome sous-capsulaire du foie</span></li>\n        <li><span class=\"kw-clinique\">Complication obstétricale</span> : <span class=\"kw-alerte\">hématome rétroplacentaire (HRP)</span></li>\n      </ul>\n      <p><strong>Complications fœtales</strong> (atteinte vasculaire utéro-placentaire)</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Hypoxie fœtale aiguë</span> : si HRP ou éclampsie</li>\n        <li><span class=\"kw-clinique\">Hypoxie fœtale chronique</span> : <span class=\"kw-alerte\">RCIU</span> (pas de parallélisme strict avec les chiffres tensionnels) et <span class=\"kw-clinique\">oligoamnios</span></li>\n        <li><span class=\"kw-alerte\">Mort fœtale in utero</span> : sur RCIU sévère ou accident aigu (éclampsie, HRP)</li>\n        <li><span class=\"kw-clinique\">Prématurité induite</span> pour sauvetage maternel ou fœtal</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 30 — Prématurité · RCIU · 24 — Complications de la <span class=\"kw-ci\">grossesse</span> · objectif « complications de la pré-éclampsie » (détail)</em></p>","frequence":1},{"id":"344-3","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l'incidence et les facteurs de risques de pré-éclampsie","contenu":"<p><strong><span class=\"kw-def\">Incidence</span></strong></p>\n      <table >\n        <thead><tr><th></th><th>Données</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>HTA &amp; grossesse</strong></span></td><td><span class=\"kw-chiffre\">5-10 %</span> des grossesses ; <span class=\"kw-def\">incidence</span> <strong>en augmentation</strong> (<span class=\"kw-etio\">obésité</span>, syndrome métabolique)</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Pré-éclampsie</strong></span></td><td><span class=\"kw-def\">prévalence</span> <span class=\"kw-chiffre\">≈ 2 %</span> ; <span class=\"kw-chiffre\">10 %</span> des femmes hypertendues de la <span class=\"kw-ci\">grossesse</span> feront une PE</td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Mortalité</strong></span></td><td><span class=\"kw-chiffre\">2ᵉ cause</span> de <span class=\"kw-def\">mortalité</span> maternelle d'origine obstétricale (après l'hémorragie de la délivrance)</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-def\">Facteurs de risque</span> de pré-éclampsie</strong></p>\n      <div class=\"callout callout-info\">\n        <strong>Génétiques</strong>\n        <ul>\n          <li>ATCD familiaux de PE</li>\n          <li>Ethnie à <span class=\"kw-clinique\">peau noire</span></li>\n          <li>Fœtus de sexe masculin</li>\n        </ul>\n      </div>\n      <ul>\n        <li><span class=\"kw-clinique\"><strong>Âge</strong></span> : <span class=\"kw-chiffre\">&lt; 20 ans</span> ou <span class=\"kw-chiffre\">&gt; 30 ans</span></li>\n        <li><span class=\"kw-clinique\"><strong>Pathologies maternelles</strong></span> : pathologies CV, <span class=\"kw-etio\">obésité</span>, insulinorésistance, diabète, HTA, pathologie rénale chronique, thrombophilie <span class=\"kw-etio\">héréditaire</span> ou acquise (<span class=\"kw-etio\">SAPL</span>)</li>\n        <li><span class=\"kw-clinique\"><strong>Immunologiques</strong></span> (temps d'exposition au sperme court) : nulliparité / primiparité (RR 3), primipaternité, changement de partenaire, insémination avec donneur (<span class=\"kw-clinique\">PMA</span>)</li>\n        <li><span class=\"kw-clinique\"><strong>Environnementaux</strong></span> : hypoxie d'altitude, stress, travail</li>\n        <li><span class=\"kw-clinique\"><strong>Liés à la grossesse</strong></span> : ATCD de <span class=\"kw-ci\">grossesse</span> compliquée de PE ou d'HTAg, grossesse multiple, môle hydatiforme, anasarque fœtal (surdistension utérine), anomalies chromosomiques/congénitales, intervalle long entre <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span> g</span>rossesses</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 24 — Complications de la <span class=\"kw-ci\">grossesse</span> · 253 — <span class=\"kw-etio\">Obésité</span> · 247 — Diabète</em></p>","frequence":1},{"id":"344-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les complications de la pré-éclampsie","contenu":"<p>L'atteinte vasculaire explique des complications maternelles et fœtales <span class=\"kw-alerte\">parfois graves, pouvant engager le pronostic vital</span>. Cinq complications majeures sont à connaître.</p>\n\n      <div class=\"callout callout-danger\">\n        <strong>① Crise d'éclampsie</strong> — crise convulsive tonicoclonique généralisée\n        <ul>\n          <li>Complique <span class=\"kw-chiffre\">1-3 %</span> des PE (<span class=\"kw-chiffre\">5-10 %</span> si HELLP)</li>\n          <li>À évoquer devant toute <span class=\"kw-clinique\">convulsion ou trouble de la conscience</span> pendant la <span class=\"kw-ci\">grossesse</span>, l'accouchement ou les heures/jours du post-partum</li>\n          <li>Signes annonciateurs : <span class=\"kw-clinique\">céphalées rebelles</span>, <span class=\"kw-clinique\">phosphènes</span>, <span class=\"kw-clinique\">acouphènes</span>, troubles visuels (« flash »), <span class=\"kw-clinique\">ROT vifs et polycinétiques</span>, barre épigastrique, ascension tensionnelle rapide</li>\n          <li>Principal DD : <span class=\"kw-etio\">embolie amniotique</span> (collapsus CV, <span class=\"kw-alerte\">SDRA</span>)</li>\n          <li>Traitement : <span class=\"kw-ttt\">sulfate de magnésium (MgSO₄)</span> + extraction fœtale si <span class=\"kw-alerte\">urgence</span> vitale</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-danger\">\n        <strong>② HELLP syndrome</strong> — <em>Hemolysis, Elevated Liver enzymes, Low Platelets</em>\n        <ul>\n          <li>Microangiopathie <span class=\"kw-etio\">thrombotique</span> à atteinte hépatique prédominante ; complique <span class=\"kw-chiffre\">4-10 %</span> des PE (<span class=\"kw-chiffre\">25-30 %</span> en post-partum)</li>\n          <li><span class=\"kw-clinique\">Clinique</span> : douleur épigastrique <strong>« en barre »</strong> ou de l'hypochondre droit</li>\n          <li><span class=\"kw-bio\">Hémolyse</span> : haptoglobine effondrée, <span class=\"kw-bio\">bilirubine</span> ↑, <span class=\"kw-chiffre\">LDH &gt; 600 UI/L</span>, schizocytes</li>\n          <li><span class=\"kw-bio\">Cytolyse</span> : <span class=\"kw-bio\">ASAT</span> ou <span class=\"kw-bio\">ALAT</span> <span class=\"kw-chiffre\">&gt; 70 UI/L</span> (&gt; 2N)</li>\n          <li><span class=\"kw-bio\">Thrombopénie</span> : <span class=\"kw-bio\">plaquettes</span> <span class=\"kw-chiffre\">&lt; 100 G/L</span></li>\n          <li><span class=\"kw-imagerie\">Échographie abdominale</span> : rechercher un hématome sous-capsulaire du foie</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-danger\">\n        <strong>③ Hématome rétroplacentaire (HRP)</strong> — décollement prématuré du placenta normalement inséré\n        <ul>\n          <li>Triade clinique : <span class=\"kw-clinique\">métrorragies noirâtres incoagulables</span> (peu abondantes), <span class=\"kw-clinique\">douleur abdominale brutale « en coup de poignard »</span>, <span class=\"kw-clinique\">contracture utérine permanente « ventre de bois »</span></li>\n          <li>ARCF constantes, <span class=\"kw-alerte\">état de choc sans rapport</span> avec l'abondance de l'hémorragie</li>\n          <li>Forme complète (mort fœtale) → <span class=\"kw-alerte\">CIVD constante</span> par défibrination</li>\n          <li><span class=\"kw-imagerie\">Échographie</span> : élimine un placenta praevia (l'absence d'hématome visible n'élimine pas le diagnostic)</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-danger\">\n        <strong>④ <span class=\"kw-ci\">Insuffisance rénale</span> aiguë</strong>\n        <ul>\n          <li>Aggrave le <span class=\"kw-def\">pronostic</span> maternel ; <span class=\"kw-alerte\">OAP associé dans 50 %</span> des cas</li>\n          <li><span class=\"kw-bio\">Histologie</span> : <span class=\"kw-clinique\">nécrose</span> tubulaire aiguë + endothéliose glomérulaire (lésions <span class=\"kw-clinique\">réversibles</span>)</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-danger\">\n        <strong>⑤ Hémorragies cérébro-méningées &amp; PRES</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">AVC hémorragique</span> sur lésions endothéliales de la PE</li>\n          <li><span class=\"kw-radio\">PRES</span> (encéphalopathie postérieure réversible) : <span class=\"kw-clinique\">œdème</span> vasogénique pariéto-occipital, <span class=\"kw-imagerie\">hyperT2-FLAIR</span> à l'<span class=\"kw-imagerie\">IRM</span>, cliniquement bruyant (troubles visuels)</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 340 — <span class=\"kw-alerte\">AVC</span> · 348 — IRA · 24 — Complications de la <span class=\"kw-ci\">grossesse</span></em></p>","frequence":3,"liens":[{"href":"https://radiopaedia.org/articles/posterior-reversible-encephalopathy-syndrome","label":"Radiopaedia : PRES (encéphalopathie postérieure réversible)"},{"href":"https://radiopaedia.org/articles/placental-abruption","label":"Radiopaedia : Placental abruption (HRP)"}]},{"id":"344-5","rang":"A","rubrique":"Diagnostic","titre":"Connaître les éléments du bilan clinique d'une pré-éclampsie","contenu":"<p>L'évaluation est <span class=\"kw-clinique\">anesthésique, obstétricale et pédiatrique</span> : ces trois axes doivent être examinés à chaque temps de la prise en charge. L'objectif principal de l'examen est de <strong>distinguer les formes légères/modérées des formes sévères</strong>.</p>\n      <p><strong>Bilan maternel clinique</strong></p>\n      <ul>\n        <li>Scope <span class=\"kw-clinique\">PA, FC, FR</span> ; état de conscience</li>\n        <li><span class=\"kw-clinique\">Œdèmes</span> (face, membres sup/inf, ascite), prise de poids</li>\n        <li>Recherche d'<span class=\"kw-alerte\">OAP</span> : <span class=\"kw-alerte\">détresse</span> respiratoire, <span class=\"kw-clinique\">crépitants</span>/sibilants</li>\n        <li><span class=\"kw-alerte\">Insuffisance rénale</span> : bilan entrée-sortie, quantification de la diurèse</li>\n        <li>Signes d'<span class=\"kw-alerte\">éclampsie</span> : <span class=\"kw-clinique\">céphalées</span>, troubles visuels, acouphènes, phosphènes, ROT vifs et polycinétiques</li>\n        <li>Signes de <span class=\"kw-alerte\">HELLP</span> : douleur épigastrique, <span class=\"kw-clinique\">nausées</span>, vomissements</li>\n        <li>Signes de <span class=\"kw-alerte\">HRP</span> : métrorragies noires, contracture utérine douloureuse permanente, <span class=\"kw-alerte\">choc</span> <span class=\"kw-etio\">hémorragique</span></li>\n      </ul>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-def\">Critères de</span> sévérité (<span class=\"kw-chiffre\">≥ 1</span> critère → <span class=\"kw-alerte\">hospitalisation</span> en milieu spécialisé)</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">HTA sévère</span> : <span class=\"kw-chiffre\">PAS &gt; 160 ou PAD &gt; 110 mmHg</span>, ou non contrôlée</li>\n          <li><span class=\"kw-alerte\">Oligurie</span> &lt; <span class=\"kw-chiffre\">500 mL/24 h</span> (ou <span class=\"kw-chiffre\">≤ 25 mL/h</span>)</li>\n          <li>Barre épigastrique</li>\n          <li>Signes neurologiques persistants (<span class=\"kw-clinique\">céphalées</span>, ROT vifs polycinétiques, troubles visuels)</li>\n          <li><span class=\"kw-alerte\">OAP</span></li>\n          <li>Hématome rétroplacentaire</li>\n          <li>Convulsion ou troubles de la conscience</li>\n        </ul>\n        <strong>Critères biologiques de sévérité</strong>\n        <ul>\n          <li><span class=\"kw-bio\">Protéinurie</span> <span class=\"kw-chiffre\">&gt; 3 g/24 h</span></li>\n          <li><span class=\"kw-bio\">Créatininémie</span> <span class=\"kw-chiffre\">&gt; 90 µmol/L</span></li>\n          <li><span class=\"kw-bio\">ASAT/ALAT</span> <span class=\"kw-chiffre\">&gt; 2N</span></li>\n          <li><span class=\"kw-bio\">Thrombopénie</span> <span class=\"kw-chiffre\">&lt; 100 G/L</span></li>\n        </ul>\n      </div>\n      <p><strong>Retentissement fœtal (clinique)</strong></p>\n      <ul>\n        <li>Mesure de la <span class=\"kw-clinique\">hauteur utérine</span> (recherche d'un RCIU)</li>\n        <li>Appréciation des <span class=\"kw-clinique\">mouvements actifs fœtaux</span> (vitalité)</li>\n        <li>Auscultation des bruits du cœur fœtal</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Voir aussi : objectif « examens complémentaires en <span class=\"kw-chiffre\">première intention</span> » · objectif « retentissement fœtal »</em></p>","frequence":0},{"id":"344-6","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires à réaliser en première intention","contenu":"<div class=\"callout callout-info\"><strong>Examen indispensable.</strong> Sur le plan maternel, le <span class=\"kw-bio\">dosage de la protéinurie</span> (échantillon puis recueil des urines de <span class=\"kw-chiffre\">24 h</span>) est le <strong>seul examen indispensable</strong>. Les autres examens sont réalisés en présence de <span class=\"kw-alerte\">signes de gravité</span>, pour diagnostiquer les complications.</div>\n      <p><strong>Bilan <span class=\"kw-ttt\">biologique</span> systématique</strong> (recherche des complications)</p>\n      <ul>\n        <li><span class=\"kw-bio\">TP, TCA, fibrinogène</span> → recherche d'une <span class=\"kw-alerte\">CIVD</span></li>\n        <li><span class=\"kw-bio\">NFS, frottis, haptoglobine, LDH, bilan hépatique (ASAT/ALAT)</span> → recherche d'un <span class=\"kw-alerte\">HELLP</span></li>\n        <li><span class=\"kw-bio\">Uricémie</span>, <span class=\"kw-bio\">créatininémie</span>, <span class=\"kw-bio\">ionogramme sanguin</span> → recherche d'une <span class=\"kw-alerte\">insuffisance rénale</span></li>\n        <li><span class=\"kw-bio\">Protéinurie</span> quantitative (échantillon puis <span class=\"kw-chiffre\">24 h</span>)</li>\n      </ul>\n      <p><strong>Imagerie maternelle selon le contexte</strong></p>\n      <ul>\n        <li><span class=\"kw-imagerie\">Fond d'œil</span> : si <span class=\"kw-etio\">HTA</span> sévère ou troubles visuels</li>\n        <li><span class=\"kw-imagerie\">Échographie hépatique</span> : si HELLP ou barre épigastrique (hématome sous-capsulaire)</li>\n        <li><span class=\"kw-radio\">Imagerie cérébrale (TDM/IRM)</span> : si crise convulsive (recherche d'un PRES ou d'un DD)</li>\n      </ul>\n      <p><strong>Bilan fœtal paraclinique</strong></p>\n      <ul>\n        <li><span class=\"kw-imagerie\">Échographie obstétricale</span> : estimation du poids, vitalité (<span class=\"kw-clinique\">score de Manning</span>), liquide amniotique, <span class=\"kw-clinique\">dopplers</span> (artères ombilicales et cérébrales ± utérines)</li>\n        <li><span class=\"kw-clinique\">Enregistrement cardiotocographique (RCF)</span> : nécessaire après <span class=\"kw-chiffre\">≈ 25-26 SA</span></li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span class=\"kw-ci\">Grossesse</span> normale · 30 — RCIU · objectif « bilan clinique »</em></p>","frequence":1},{"id":"344-7","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les éléments d'anamnèse permettant d'identifier un retentissement fœtal de la pré-éclampsie","contenu":"<p>Le retentissement fœtal de la pré-éclampsie traduit l'<span class=\"kw-alerte\">insuffisance utéro-placentaire</span>. Il se dépiste d'abord à l'anamnèse et à l'examen clinique, avant confirmation paraclinique.</p>\n      <p><strong>Anamnèse &amp; clinique évoquant un retentissement fœtal</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Diminution des mouvements actifs fœtaux</span> (perte de vitalité fœtale)</li>\n        <li><span class=\"kw-clinique\">Hauteur utérine inférieure à la normale</span> (faisant suspecter un RCIU)</li>\n      </ul>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\"><span class=\"kw-def\">Critères de</span> gravité</span> du retentissement fœtal</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">RCIU sévère au-delà de 32 SA</span></li>\n          <li><span class=\"kw-clinique\">Oligoamnios</span></li>\n          <li>Anomalies sévères des <span class=\"kw-clinique\">dopplers fœtaux</span></li>\n          <li><span class=\"kw-alerte\">Toute anomalie du rythme cardiaque fœtal</span></li>\n        </ul>\n      </div>\n      <p><strong>Apport des dopplers fœtaux</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Artères ombilicales</span> : altération = ↓ vitesses diastoliques → <span class=\"kw-alerte\">diastole nulle</span> → <span class=\"kw-alerte\">reverse flow</span> (gravité croissante)</li>\n        <li><span class=\"kw-clinique\">Artères cérébrales</span> : hypoxie → ↓ résistances (redistribution du flux vers le cerveau fœtal) en faveur d'une cause vasculaire</li>\n        <li><span class=\"kw-clinique\">Artères utérines</span> : persistance d'un <span class=\"kw-clinique\">notch</span> (incisure protodiastolique) après 24 SA = malplacentation</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 30 — Prématurité · RCIU · objectif « examens complémentaires »</em></p>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/umbilical-artery-doppler-assessment","label":"Radiopaedia : Doppler des artères ombilicales"}]},{"id":"344-8","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge de la pré-éclampsie","contenu":"<div class=\"callout callout-danger\"><strong>Principe fondamental.</strong> Le <strong>seul traitement curatif</strong> de la pré-éclampsie est l'<span class=\"kw-alerte\">arrêt de la grossesse et la délivrance du placenta</span>. Le traitement anti-<span class=\"kw-etio\">HTA</span> n'est qu'un <strong>adjuvant</strong> : il n'influence pas l'<span class=\"kw-clinique\">évolution</span> car l'HTA n'est qu'un symptôme d'une maladie polyviscérale.</div>\n      <p>La prise en charge impose un <span class=\"kw-clinique\">transfert materno-fœtal</span> vers un centre de médecine périnatale de niveau adapté au terme et au poids fœtal estimé.</p>\n\n      <p><strong>Traitement antihypertenseur</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Indication</span> : <span class=\"kw-etio\">HTA</span> sévère (<span class=\"kw-chiffre\">PAS ≥ 160 et/ou PAD ≥ 110 mmHg</span>)</li>\n        <li><span class=\"kw-clinique\">Objectifs avant extraction</span> : PAS <span class=\"kw-chiffre\">140-160</span> · PAD <span class=\"kw-chiffre\">85-100 mmHg</span></li>\n        <li><span class=\"kw-clinique\">Objectifs après extraction</span> : cible plus stricte <span class=\"kw-chiffre\">~120/80 mmHg</span> (le placenta n'est plus en jeu)</li>\n        <li><span class=\"kw-alerte\">Risque</span> : l'<span class=\"kw-clinique\">hypotension</span> maternelle aggrave l'hypoxie fœtale (↓ perfusion utéro-placentaire)</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>Les <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>5</span> an</span>ti-<span class=\"kw-etio\">HTA</span> utilisables (par ordre)</strong>\n        <ul>\n          <li><span class=\"kw-ttt\">Alpha-méthyldopa</span> (central) — 1ʳᵉ intention ; innocuité fœtale ; CI si <span class=\"kw-ci\">insuffisance hépatique</span></li>\n          <li><span class=\"kw-ttt\">Labétalol</span> (α/β-bloquant) — 1ʳᵉ intention selon la SFAR en cas de PE</li>\n          <li><span class=\"kw-ttt\">Nicardipine / nifédipine</span> (<span class=\"kw-ttt\">inhibiteur calcique</span>) — tocolytique, risque de chute brutale de PA</li>\n          <li><span class=\"kw-ttt\">Urapidil</span> (α-bloquant)</li>\n          <li><span class=\"kw-ttt\">Clonidine</span> (central) — en dernière intention</li>\n        </ul>\n      </div>\n      <div class=\"callout callout-danger\">\n        <strong>Anti-<span class=\"kw-etio\">HTA</span> <span class=\"kw-ci\">contre-indiqués</span></strong>\n        <ul>\n          <li><span class=\"kw-ci\">IEC et ARA2</span> : <strong>CI quel que soit le terme</strong> (fœtotoxiques : malformations, oligoamnios, toxicité rénale néonatale)</li>\n          <li><span class=\"kw-ci\">Diurétiques</span> : CI (aggravent l'ischémie utéro-placentaire), sauf <span class=\"kw-ci\">insuffisance cardiaque</span></li>\n          <li><span class=\"kw-ci\">β-bloquants</span> : risque de RCIU, hypoglycémie et <span class=\"kw-clinique\">bradycardie</span> néonatales</li>\n        </ul>\n      </div>\n      <p><strong>Mesures non médicamenteuses</strong> : repos (arrêt de travail), décubitus latéral gauche, <span class=\"kw-clinique\">régime normalement salé</span> (le <span class=\"kw-ci\">régime sans sel est contre-indiqué</span> : il aggrave l'hypovolémie).</p>\n\n      <p><strong>PEC d'une pré-éclampsie sévère</strong> (sans critère d'extraction en <span class=\"kw-alerte\">urgence</span>)</p>\n      <ul>\n        <li>Orientation en <span class=\"kw-clinique\">réanimation / USC</span></li>\n        <li><span class=\"kw-ci\">Pas de remplissage vasculaire systématique</span> (risque d'<span class=\"kw-alerte\">OAP</span>)</li>\n        <li><span class=\"kw-ttt\">Sulfate de magnésium</span> à discuter en prophylaxie de l'éclampsie</li>\n        <li>Anti-<span class=\"kw-etio\">HTA</span> : <span class=\"kw-ttt\">labétalol</span> (1ʳᵉ intention SFAR), puis nicardipine IV ou urapidil</li>\n        <li>Attitude conservatrice <strong><span class=\"kw-chiffre\">48 h</span></strong> : <span class=\"kw-ttt\">corticothérapie anténatale</span> (2 injections IM de bétaméthasone à<span class=\"kw-chiffre\"> 24 h</span> si <span class=\"kw-chiffre\">&lt; 34 SA</span>), MgSO₄ neuroprotecteur si <span class=\"kw-chiffre\">&lt; 32 SA</span> et naissance imminente</li>\n      </ul>\n      <p><strong>PEC d'une pré-éclampsie modérée</strong> : <span class=\"kw-alerte\">hospitalisation</span>, antihypertenseur per os (<span class=\"kw-ttt\">inhibiteurs calciques</span>, α/β-bloquants, α-méthyldopa), attitude conservatrice.</p>\n\n      <div class=\"callout callout-danger\">\n        <strong>Critères imposant l'extraction fœtale en <span class=\"kw-alerte\">urgence</span> et sans délai</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">Maternels</span> : <span class=\"kw-etio\">HTA</span> sévère non contrôlée par bithérapie, crise d'éclampsie, <span class=\"kw-clinique\">céphalées</span>/troubles visuels, HELLP, <span class=\"kw-alerte\">CIVD</span>, HRP clinique ou échographique</li>\n          <li><span class=\"kw-alerte\">Fœtaux</span> : RCIU important / arrêt de croissance, oligoamnios sévère, RCF pathologique, doppler ombilical pathologique</li>\n        </ul>\n      </div>\n      <p><strong>Quand provoquer l'accouchement ?</strong></p>\n      <ul>\n        <li>PE <strong>sévère</strong> : ne pas poursuivre la <span class=\"kw-ci\">grossesse</span> au-delà de <span class=\"kw-chiffre\">34 SA</span></li>\n        <li>PE <strong>modérée</strong> : ne pas poursuivre au-delà de <span class=\"kw-chiffre\">37-38 SA</span></li>\n        <li>PE sévère et très précoce (<span class=\"kw-chiffre\">&lt; 24 SA</span>) : faire discuter une <span class=\"kw-alerte\">IMG</span> (sauvetage maternel)</li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        <strong>Sulfate de magnésium (MgSO₄) — éclampsie</strong>\n        <ul>\n          <li>Administration : <span class=\"kw-chiffre\">dose de charge 4 g IV</span> sur <span class=\"kw-chiffre\">20 min</span>, puis <span class=\"kw-chiffre\">1-2 g/h</span> IVSE jusqu'à<span class=\"kw-chiffre\"> 24 h</span> après l'accouchement ou la dernière crise</li>\n          <li><span class=\"kw-ci\">CI</span> : <span class=\"kw-ci\">insuffisance rénale</span>, maladies neuromusculaires</li>\n          <li>Surdosage (<span class=\"kw-clinique\">bradypnée</span>, hypoTA, oligurie, ROT abolis) → antidote = <span class=\"kw-ttt\">gluconate de calcium</span></li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 326 — Cadre réglementaire de la prescription et bon usage du médicament · 332 — États de <span class=\"kw-alerte\">choc</span> · objectif « prévention des complications »</em></p>","frequence":6},{"id":"344-9","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de prévention des complications de la pré-éclampsie","contenu":"<p>La prévention des complications repose sur le <span class=\"kw-def\">dépistage</span> précoce des <span class=\"kw-def\">critères de</span> sévérité, la prophylaxie de l'éclampsie et la prévention de la prématurité.</p>\n      <p><strong>Prévention de l'éclampsie — sulfate de magnésium</strong></p>\n      <ul>\n        <li><span class=\"kw-ttt\">Prévention secondaire</span> : <strong>systématique</strong> pour prévenir une récidive de crise convulsive</li>\n        <li><span class=\"kw-ttt\">Prévention primaire</span> : discutée chez les patientes pré-éclamptiques <span class=\"kw-alerte\">sévères à risque d'éclampsie</span></li>\n      </ul>\n      <p><strong>Prévention des complications de la prématurité induite</strong></p>\n      <ul>\n        <li><span class=\"kw-ttt\">Corticothérapie anténatale</span> : 2 injections IM de bétaméthasone à<span class=\"kw-chiffre\"> 24 h</span> d'intervalle si terme <span class=\"kw-chiffre\">&lt; 34 SA</span> (maturation pulmonaire)</li>\n        <li><span class=\"kw-ttt\">MgSO₄ neuroprotecteur</span> : si terme <span class=\"kw-chiffre\">&lt; 32 SA</span> et naissance imminente</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>Autres mesures préventives</strong>\n        <ul>\n          <li>Anti-<span class=\"kw-etio\">HTA</span> en cas d'HTA sévère pour <span class=\"kw-clinique\">éviter les à-coups tensionnels</span> → prévention de l'hémorragie cérébrale</li>\n          <li><span class=\"kw-ci\">Pas de remplissage vasculaire systématique</span> → prévention de l'<span class=\"kw-alerte\">OAP</span></li>\n          <li><span class=\"kw-alerte\">Hospitalisation</span> et <span class=\"kw-clinique\">surveillance materno-fœtale rapprochée</span> dès la présence d'un <span class=\"kw-def\">critère de</span> sévérité</li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Voir aussi : objectif « prise en charge de la pré-éclampsie » · objectif « <span class=\"kw-def\">surveillance</span> »</em></p>","frequence":0},{"id":"344-10","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les principes de la surveillance de la pré-éclampsie","contenu":"<p>La <span class=\"kw-def\">surveillance</span> est <span class=\"kw-clinique\">materno-fœtale</span>, d'intensité adaptée à la sévérité, et se poursuit dans le post-partum car les complications restent possibles plusieurs jours après l'accouchement.</p>\n      <p><strong>Pendant la <span class=\"kw-ci\">grossesse</span></strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">HTA légère / modérée</span> : <span class=\"kw-def\">surveillance</span> ambulatoire, <span class=\"kw-clinique\">carnet « Grossesse et HTA »</span>, consultation tous les <span class=\"kw-chiffre\">10 jours</span>, bilan <span class=\"kw-ttt\">biologique</span> régulier, <span class=\"kw-imagerie\">échographie</span> mensuelle avec doppler utérin</li>\n        <li><span class=\"kw-alerte\">PE sévère</span> : <span class=\"kw-def\">surveillance</span> materno-fœtale étroite en <span class=\"kw-alerte\">hospitalisation</span> (réa/USC)</li>\n      </ul>\n      <p><strong>Post-partum immédiat</strong></p>\n      <ul>\n        <li><span class=\"kw-def\">Surveillance</span> maternelle <span class=\"kw-alerte\">étroite</span> : complications possibles dans les <span class=\"kw-chiffre\">7 jours</span> suivant l'accouchement</li>\n        <li>Examen <span class=\"kw-clinique\">anatomopathologique du placenta</span></li>\n        <li>Arrêt <span class=\"kw-clinique\">progressif</span> du traitement antihypertenseur (l'<span class=\"kw-etio\">HTA</span> peut mettre plusieurs semaines à disparaître)</li>\n        <li><span class=\"kw-ci\">Pas de contraception œstroprogestative</span> immédiate (surrisque <span class=\"kw-etio\">thrombotique</span>)</li>\n      </ul>\n      <p><strong>Consultations de <span class=\"kw-def\">suivi</span></strong></p>\n      <table >\n        <thead><tr><th>Échéance</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\"><strong>6-8 semaines</strong></span></td><td>contrôle de la régression de la PA et de la <span class=\"kw-bio\">protéinurie</span> (<span class=\"kw-bio\">BU</span>) ; avis néphrologique / médecine interne ; recherche de <span class=\"kw-etio\">SAPL</span> si PE sévère ou précoce</td></tr>\n          <tr><td><span class=\"kw-chiffre\"><strong>3 mois</strong></span></td><td>bilan vasculo-rénal : PA, <span class=\"kw-bio\">créatininémie</span>, <span class=\"kw-bio\">protéinurie</span>/<span class=\"kw-bio\">albuminurie</span> des <span class=\"kw-chiffre\">24 h</span> (<span class=\"kw-def\">dépistage</span> d'une <span class=\"kw-etio\">HTA</span> chronique ou d'une néphropathie sous-jacente)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 34 — Suites de couches pathologiques · 36 — Contraception · 264 — IRC</em></p>","frequence":0},{"id":"344-11","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les éléments de prévention pour la grossesse suivante","contenu":"<div class=\"callout callout-info\"><strong>Risque de récidive.</strong> Le risque de récidive de pré-éclampsie pour une future <span class=\"kw-ci\">grossesse</span> est de <span class=\"kw-chiffre\">20 à 25 %</span>. Une <span class=\"kw-clinique\">visite pré-conceptionnelle</span> est à prévoir.</div>\n      <p><strong>Prévention par <span class=\"kw-ttt\">aspirine</span> à faible dose</strong></p>\n      <ul>\n        <li><span class=\"kw-ttt\">Posologie</span> : <span class=\"kw-chiffre\">75-100 à 160 mg/jour</span></li>\n        <li><span class=\"kw-clinique\">Quand</span> : à débuter <span class=\"kw-chiffre\">avant 16 SA</span>, jusqu'à <span class=\"kw-chiffre\">36 SA</span> (au-delà de 20 SA le traitement n'est plus efficace pour réduire le risque)</li>\n        <li><span class=\"kw-clinique\">Indication</span> : ATCD de <span class=\"kw-alerte\">RCIU sévère</span> ou de <span class=\"kw-alerte\">pré-éclampsie précoce et/ou sévère</span> avec prématurité induite</li>\n      </ul>\n      <p><strong><span class=\"kw-def\">Surveillance</span> renforcée de la <span class=\"kw-ci\">grossesse</span> suivante</strong></p>\n      <ul>\n        <li><span class=\"kw-imagerie\">Doppler des artères utérines</span> : une faible diastole ou un notch protodiastolique peut précéder de plusieurs semaines l'<span class=\"kw-etio\">HTA</span> ou le RCIU</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Ce qui n'est plus indiqué.</strong> Une pré-éclampsie, associée ou non à un RCIU, ne justifie <strong>plus</strong> la recherche systématique d'une <span class=\"kw-etio\">pathologie auto-immune (SAPL)</span> ou d'une <span class=\"kw-etio\">thrombophilie congénitale</span> (déficit en antithrombine, protéine S/C, mutation Leiden du facteur V).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 24 — Complications de la <span class=\"kw-ci\">grossesse</span> · objectif « <span class=\"kw-def\">surveillance</span> » · 27 — Prévention des risques fœtaux</em></p>","frequence":2}],"astuces":[],"strategie":{"urgence":"<p><strong>Crise d'éclampsie <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> vitale immédiate</span></strong></p><p><span class=\"kw-ttt\">sulfate de magnésium</span> (<span class=\"kw-chiffre\">4 g</span> IV puis <span class=\"kw-chiffre\">1-2 g</span>/h) + <span class=\"kw-alerte\">extraction fœtale</span></p><ul><li>Convulsion ou trouble de conscience pendant la <span class=\"kw-ci\">grossesse</span>, l'accouchement ou le post-partum</li><li>DD principal : <span class=\"kw-etio\">embolie amniotique</span></li></ul><p><strong>Extraction fœtale en <span class=\"kw-alerte\">urgence</span> <span class=\"q\">— sans délai, quel que soit le terme</span></strong></p><ul><li><span class=\"kw-alerte\">Maternel</span> : <span class=\"kw-etio\">HTA</span> sévère non contrôlée par bithérapie, éclampsie, <span class=\"kw-alerte\">HELLP</span>, <span class=\"kw-alerte\">CIVD</span>, <span class=\"kw-alerte\">HRP</span></li><li><span class=\"kw-alerte\">Fœtal</span> : ARCF, doppler ombilical pathologique, RCIU avec arrêt de croissance, oligoamnios sévère</li></ul><p><strong>Accouchement programmé <span class=\"q\">— ne pas dépasser</span></strong></p><ul><li>PE <strong>sévère</strong> : <span class=\"kw-chiffre\">≤ 34 SA</span></li><li>PE <strong>modérée</strong> : <span class=\"kw-chiffre\">37-38 SA</span></li><li>PE sévère très précoce (<span class=\"kw-chiffre\">&lt; 24 SA</span>) → discuter une <span class=\"kw-alerte\">IMG</span> (sauvetage maternel)</li></ul>","hospit":"<p><strong><span class=\"kw-etio\">HTA</span> gravidique / PE légère à modérée</strong></p><ul><li><span class=\"kw-def\">Surveillance</span> <span class=\"kw-clinique\">ambulatoire</span> possible : <span class=\"kw-clinique\">carnet « Grossesse et HTA »</span>, consultation tous les <span class=\"kw-chiffre\">10 jours</span></li></ul><p><strong>PE modérée</strong></p><ul><li><span class=\"kw-clinique\">Hospitalisation</span> conventionnelle, anti-<span class=\"kw-etio\">HTA</span> per os, attitude conservatrice</li></ul><p><strong>PE sévère</strong></p><ul><li>Orientation en <span class=\"kw-alerte\">réanimation / USC</span></li><li><span class=\"kw-clinique\">Transfert materno-fœtal in utero</span> vers un centre de médecine périnatale de niveau adapté au terme et au poids fœtal</li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">HTA sévère</span> : PAS <span class=\"kw-chiffre\">≥ 160</span> et/ou PAD <span class=\"kw-chiffre\">≥ 110 mmHg</span>, ou non contrôlée</li><li>Signes neuro : <span class=\"kw-clinique\">céphalées rebelles</span>, <span class=\"kw-clinique\">phosphènes</span>, <span class=\"kw-clinique\">acouphènes</span>, troubles visuels, <span class=\"kw-clinique\">ROT vifs et polycinétiques</span></li><li><span class=\"kw-clinique\">Barre épigastrique</span> (évoque un <span class=\"kw-alerte\">HELLP</span>)</li><li><span class=\"kw-alerte\">Oligurie</span> &lt; <span class=\"kw-chiffre\">500 mL/24 h</span> (ou <span class=\"kw-chiffre\">≤ 25 mL</span>/h)</li><li><span class=\"kw-alerte\">OAP</span> (<span class=\"kw-alerte\">détresse</span> respiratoire, <span class=\"kw-clinique\">crépitants</span>)</li><li><span class=\"kw-alerte\">HRP</span> : métrorragies noirâtres, contracture utérine « ventre de bois », <span class=\"kw-alerte\">choc</span></li><li><span class=\"kw-alerte\">Convulsion ou trouble de la conscience</span> (éclampsie)</li><li>Retentissement fœtal : <span class=\"kw-alerte\">RCIU sévère</span> &gt; 32 SA, <span class=\"kw-clinique\">oligoamnios</span>, doppler ombilical pathologique, <span class=\"kw-alerte\">anomalie du RCF</span></li></ul>","principes":"<p>Le <strong>seul traitement curatif</strong> est l'<span class=\"kw-alerte\">arrêt de la grossesse et la délivrance du placenta</span> : l'anti-<span class=\"kw-etio\">HTA</span> n'est qu'un <strong>adjuvant</strong> (l'HTA n'est qu'un symptôme d'une maladie polyviscérale).</p><p><strong>Traitement antihypertenseur</strong></p><ul><li>Indication : <span class=\"kw-alerte\">HTA sévère</span> (PAS <span class=\"kw-chiffre\">≥ 160</span> et/ou PAD <span class=\"kw-chiffre\">≥ 110 mmHg</span>)</li><li>Cible : PAS <span class=\"kw-chiffre\">140-160</span> · PAD <span class=\"kw-chiffre\">85-100 mmHg</span> (ne pas trop baisser : risque d'hypoxie fœtale)</li><li><span class=\"kw-ttt\">Labétalol</span> (1ʳᵉ intention SFAR), <span class=\"kw-ttt\">α-méthyldopa</span>, <span class=\"kw-ttt\">nicardipine</span>, <span class=\"kw-ttt\">urapidil</span>, <span class=\"kw-ttt\">clonidine</span></li></ul><p><strong><span class=\"kw-ci\">Contre-indications</span> <span class=\"q\">— pièges classiques</span></strong></p><ul><li><span class=\"kw-ci\">IEC et ARA2</span> : CI quel que soit le terme (fœtotoxiques)</li><li><span class=\"kw-ci\">Diurétiques</span> et <span class=\"kw-ci\">régime sans sel</span> : aggravent l'hypovolémie / l'ischémie placentaire</li><li><span class=\"kw-ci\">Pas de remplissage vasculaire systématique</span> (risque d'<span class=\"kw-alerte\">OAP</span>)</li></ul><p><strong>Sulfate de magnésium (MgSO₄)</strong></p><ul><li>Dose de charge <span class=\"kw-chiffre\">4 g IV</span>/<span class=\"kw-chiffre\">20 min</span> puis <span class=\"kw-chiffre\">1-2 g/h</span> IVSE jusqu'à<span class=\"kw-chiffre\"> 24 h</span> après l'accouchement ou la dernière crise</li><li><span class=\"kw-ci\">CI</span> : <span class=\"kw-ci\">insuffisance rénale</span>, maladies neuromusculaires</li><li>Surdosage (ROT abolis, <span class=\"kw-clinique\">bradypnée</span>) → antidote <span class=\"kw-ttt\">gluconate de calcium</span></li></ul><p><strong>Prévention de la prématurité induite</strong></p><ul><li><span class=\"kw-ttt\">Corticothérapie anténatale</span> (bétaméthasone, 2 injections IM) si <span class=\"kw-chiffre\">&lt; 34 SA</span></li><li><span class=\"kw-ttt\">MgSO₄ neuroprotecteur</span> si <span class=\"kw-chiffre\">&lt; 32 SA</span> et naissance imminente</li></ul>","suivi":"<p><strong>Pendant la <span class=\"kw-ci\">grossesse</span></strong></p><ul><li><span class=\"kw-etio\">HTA</span> légère/modérée : <span class=\"kw-def\">surveillance</span> ambulatoire, <span class=\"kw-imagerie\">échographie</span> mensuelle avec doppler utérin</li><li><span class=\"kw-alerte\">PE sévère</span> : <span class=\"kw-def\">surveillance</span> materno-fœtale étroite en <span class=\"kw-alerte\">hospitalisation</span></li></ul><p><strong>Post-partum</strong></p><ul><li><span class=\"kw-def\">Surveillance</span> <span class=\"kw-alerte\">étroite</span> : complications encore possibles dans les <span class=\"kw-chiffre\">7 jours</span></li><li><span class=\"kw-ttt\">Sevrage</span> <span class=\"kw-clinique\">progressif</span> des anti-<span class=\"kw-etio\">HTA</span> · <span class=\"kw-ci\">pas de contraception œstroprogestative</span> immédiate</li><li>Examen <span class=\"kw-clinique\">anatomopathologique du placenta</span></li></ul><p><strong>Consultations de contrôle</strong></p><ul><li><span class=\"kw-chiffre\">6-8 semaines</span> : régression PA + <span class=\"kw-bio\">protéinurie</span> ; recherche de <span class=\"kw-etio\">SAPL</span> si PE sévère/précoce</li><li><span class=\"kw-chiffre\">3 mois</span> : bilan vasculo-rénal (PA, <span class=\"kw-bio\">créatininémie</span>, <span class=\"kw-bio\">protéinurie</span> des <span class=\"kw-chiffre\">24 h</span>)</li></ul><p><strong><span class=\"kw-ci\">Grossesse</span> suivante <span class=\"q\">— récidive <span class=\"kw-chiffre\">20-25 %</span></span></strong></p><ul><li><span class=\"kw-ttt\">Aspirine faible dose</span> (<span class=\"kw-chiffre\">75-160 mg</span>/j) à débuter <span class=\"kw-chiffre\">avant 16 SA</span> → <span class=\"kw-chiffre\">36 SA</span> si ATCD de PE précoce/sévère</li><li><span class=\"kw-imagerie\">Doppler des artères utérines</span> de <span class=\"kw-def\">dépistage</span></li></ul>"},"liensGlobaux":[{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/61.%20Complications%20graves%20de%20la%20grossesse%20-%20pr%C3%A9-%C3%A9clampsie.pdf","label":"CEMIR — Complications graves de la grossesse : pré-éclampsie"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"HTA ≥ 140/90 mmHg à partir de 20 SA — Femme enceinte jusque-là normotendue","detail":"<h4>CAT — <span class=\"kw-etio\">HTA</span> à partir de 20 SA — Du diagnostic à l'orientation et au moment de l'extraction</h4>","branches":[{"to":"t-htag","label":"Pas de protéinurie","color":"green"},{"to":"q-gravite","label":"Protéinurie > 0,3 g/24 h ou ≥ 2 croix BU","color":"amber"}]},{"id":"t-htag","kind":"terminal","label":"HTA gravidique","color":"green","detail":"<h4>Définition</h4><ul><li><span class=\"kw-etio\">HTA</span> après 20 SA <strong>sans <span class=\"kw-bio\">protéinurie</span></strong>, régressive avant la fin de la 6ᵉ semaine du post-partum</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-def\">Surveillance</span> <span class=\"kw-clinique\">ambulatoire</span> (carnet « <span class=\"kw-ci\">Grossesse</span> et <span class=\"kw-etio\">HTA</span> »)</li><li>Anti-<span class=\"kw-etio\">HTA</span> seulement si <span class=\"kw-alerte\">HTA sévère</span></li><li><span class=\"kw-def\">Dépistage</span> d'une <span class=\"kw-bio\">protéinurie</span> (<span class=\"kw-bio\">BU</span> à chaque consultation)</li></ul>"},{"id":"q-gravite","kind":"decision","label":"Pré-éclampsie — signe(s) de gravité ? — HTA ≥ 160/110, signes neuro, barre épigastrique, oligurie, OAP, HELLP, HRP, éclampsie, retentissement fœtal","branches":[{"to":"t-pe-moderee","label":"Aucun critère de sévérité","color":"amber"},{"to":"q-extraction","label":"≥ 1 critère de sévérité","color":"red"}]},{"id":"t-pe-moderee","kind":"terminal","label":"PE modérée","color":"amber","detail":"<h4>Orientation</h4><ul><li><span class=\"kw-clinique\">Hospitalisation</span> conventionnelle</li></ul><h4>Traitement</h4><ul><li>Anti-<span class=\"kw-etio\">HTA</span> <span class=\"kw-clinique\">per os</span> (<span class=\"kw-ttt\">inhibiteur calcique</span>, α/β-bloquant, α-méthyldopa)</li><li>Attitude conservatrice + <span class=\"kw-def\">surveillance</span> materno-fœtale rapprochée</li></ul><h4>Délai</h4><ul><li>Ne pas poursuivre la <span class=\"kw-ci\">grossesse</span> au-delà de <span class=\"kw-chiffre\">37-38 SA</span></li></ul>"},{"id":"q-extraction","kind":"decision","label":"Critère imposant l'extraction en urgence sans délai ? — Éclampsie · HTA sévère non contrôlée par bithérapie · HELLP · CIVD · HRP · ARCF / doppler ombilical pathologique","branches":[{"to":"t-extraction","label":"Oui","color":"red"},{"to":"q-terme","label":"Non → terme ?","color":"amber"}]},{"id":"t-extraction","kind":"terminal","label":"Extraction fœtale immédiate","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Extraction sans délai</span>, quel que soit le terme</li><li><span class=\"kw-ttt\">Sulfate de magnésium</span> (<span class=\"kw-chiffre\">4 g</span> IV puis <span class=\"kw-chiffre\">1-2 g</span>/h) si éclampsie / prophylaxie</li><li>Anti-<span class=\"kw-etio\">HTA</span> IV (<span class=\"kw-ttt\">labétalol</span>, nicardipine, urapidil) — cible PAD <span class=\"kw-chiffre\">85-100 mmHg</span></li></ul><h4>Délai</h4><ul><li>Immédiat (sauvetage maternel et/ou fœtal)</li></ul><h4>Renvoi</h4><ul><li>Item 332 (états de <span class=\"kw-alerte\">choc</span>) · Item 348 (<span class=\"kw-alerte\">insuffisance rénale aiguë</span>)</li></ul>"},{"id":"q-terme","kind":"decision","label":"Terme de la grossesse ?","branches":[{"to":"t-img","label":"< 24 SA","color":"blue"},{"to":"t-pe-severe","label":"≥ 24 SA","color":"amber"}]},{"id":"t-img","kind":"terminal","label":"Discuter une IMG","color":"blue","detail":"<h4>Contexte</h4><ul><li>PE sévère très précoce (<span class=\"kw-chiffre\">&lt; 24 SA</span>)</li></ul><h4>Conduite</h4><ul><li>Discuter une <span class=\"kw-alerte\">interruption médicale de grossesse</span> (sauvetage maternel)</li></ul>"},{"id":"t-pe-severe","kind":"terminal","label":"PE sévère — attitude conservatrice","color":"amber","detail":"<h4>Orientation</h4><ul><li><span class=\"kw-alerte\">Réanimation / USC</span>, centre périnatal de niveau adapté</li></ul><h4>Traitement</h4><ul><li>Anti-<span class=\"kw-etio\">HTA</span> IV (<span class=\"kw-ttt\">labétalol</span> puis nicardipine / urapidil)</li><li><span class=\"kw-ci\">Pas de remplissage systématique</span> (risque d'<span class=\"kw-alerte\">OAP</span>)</li><li><span class=\"kw-ttt\">MgSO₄</span> en prophylaxie de l'éclampsie</li><li><span class=\"kw-ttt\">Corticoïdes</span> si &lt; 34 SA · <span class=\"kw-ttt\">MgSO₄ neuroprotecteur</span> si &lt; 32 SA</li></ul><h4>Délai</h4><ul><li>Temporisation <span class=\"kw-chiffre\">48 h</span> (maturation) puis extraction · ne pas dépasser <span class=\"kw-chiffre\">34 SA</span></li></ul>"}]},"cards":[{"i":"03ab974f6537","n":344,"o":"344-1","u":"Définition","t":"Connaître la définition de la pré-éclampsie","q":"Quel est le seuil de protéinurie à considérer pour le diagnostic de pré-éclampsie ?","a":"<ul><li>Une protéinurie <strong>supérieure à 0,3 g/24h</strong>.</li><li>Ou un ratio protéine/créatinine <strong>supérieur à 30 mg/mmol</strong>.</li><li>Ou la présence de <strong>2 croix ou plus</strong> à la bandelette urinaire (BU).</li></ul><p>Il est important de noter que la protéinurie est de type glomérulaire et que l'albuminurie seule ne fait pas partie de la définition.</p>"},{"i":"b6e16130c50f","n":344,"o":"344-1","u":"Définition","t":"Connaître la définition de la pré-éclampsie","q":"Comment définit-on cliniquement la pré-éclampsie selon les critères de l'EDN ?","a":"<p>La pré-éclampsie est définie par l'association, à partir de <strong>20 semaines d'aménorrhée (SA) ou plus</strong>, d'une <strong>hypertension artérielle (HTA)</strong> et d'une <strong>protéinurie</strong> chez une femme jusque-là normotendue.</p>"},{"i":"efc6c8041469","n":344,"o":"344-1","u":"Définition","t":"Connaître la définition de la pré-éclampsie","q":"Quels sont les seuils précis d'hypertension artérielle pour définir une pré-éclampsie ?","a":"<p>Il s'agit d'une Pression Artérielle Systolique (PAS) <strong>supérieure ou égale à 140 mmHg</strong> et/ou une Pression Artérielle Diastolique (PAD) <strong>supérieure ou égale à 90 mmHg</strong>, mesurée à <strong>au moins 2 reprises</strong>.</p>"},{"i":"12add593d83d","n":344,"o":"344-4","u":"Diagnostic positif","t":"Connaître les complications de la pré-éclampsie","q":"Quels sont les signes cliniques et échographiques d'un hématome rétroplacentaire (HRP) chez une patiente pré-éclamptique ?","a":"<p>L'hématome rétroplacentaire (HRP) est un décollement prématuré du placenta normalement inséré, complication de la pré-éclampsie.</p><ul><li>La triade clinique est la suivante : des <strong>métrorragies noirâtres incoagulables</strong> (souvent peu abondantes), une <strong>douleur abdominale brutale « en coup de poignard »</strong>, et une <strong>contracture utérine permanente « ventre de bois »</strong>.</li><li>On retrouve souvent des <strong>ARCF (anomalies du rythme cardiaque fœtal) constantes</strong> et un <strong>état de choc maternel</strong> sans rapport avec l'abondance de l'hémorragie.</li><li>À l'échographie, l'absence d'hématome visible n'élimine pas le diagnostic, mais cet examen permet d'<strong>éliminer un placenta praevia</strong>.</li></ul>"},{"i":"61f806292814","n":344,"o":"344-4","u":"Diagnostic positif","t":"Connaître les complications de la pré-éclampsie","q":"Quels sont les critères diagnostiques biologiques du HELLP syndrome, complication de la pré-éclampsie ?","a":"<p>Le HELLP syndrome (<strong>H</strong>emolysis, <strong>E</strong>levated <strong>L</strong>iver enzymes, <strong>L</strong>ow <strong>P</strong>latelets) est une microangiopathie thrombotique à atteinte hépatique prédominante.</p><ul><li><strong>Hémolyse</strong> : <strong>haptoglobine effondrée</strong>, <strong>bilirubine élevée</strong>, <strong>LDH > 600 UI/L</strong>, présence de <strong>schizocytes</strong>.</li><li><strong>Cytolyse hépatique</strong> : <strong>ASAT ou ALAT > 70 UI/L</strong> (> 2 fois la normale).</li><li><strong>Thrombopénie</strong> : <strong>plaquettes < 100 G/L</strong>.</li></ul>"},{"i":"79fc10b0aeca","n":344,"o":"344-4","u":"Diagnostic positif","t":"Connaître les complications de la pré-éclampsie","q":"Quelles sont les complications rénales et neurologiques de la pré-éclampsie ?","a":"<ul><li><strong>Insuffisance rénale aiguë</strong> : C'est une complication qui aggrave le pronostic maternel. Elle s'associe à un œdème aigu du poumon (OAP) dans 50 % des cas. Histologiquement, on observe une <strong>nécrose tubulaire aiguë</strong> et une <strong>endothéliose glomérulaire</strong>, avec des lésions potentiellement réversibles.</li><li><strong>Hémorragies cérébro-méningées et PRES (Encéphalopathie Postérieure Réversible)</strong> : La pré-éclampsie peut entraîner un <strong>AVC hémorragique</strong> dû aux lésions endothéliales. Le PRES se manifeste par un <strong>œdème vasogénique pariéto-occipital</strong> visible en <strong>hyperT2-FLAIR à l'IRM</strong>, et peut être cliniquement bruyant avec des troubles visuels.</li></ul>"},{"i":"b7290646d7ed","n":344,"o":"344-4","u":"Diagnostic positif","t":"Connaître les complications de la pré-éclampsie","q":"Qu'est-ce qu'une crise d'éclampsie dans le cadre d'une pré-éclampsie et quels sont ses signes annonciateurs ?","a":"<p>La crise d'éclampsie est une complication grave de la pré-éclampsie, caractérisée par une <strong>crise convulsive tonicoclonique généralisée</strong>. Elle survient dans 1 à 3 % des pré-éclampsies (jusqu'à 5-10 % en cas de HELLP syndrome).</p><ul><li>Les signes annonciateurs sont : des <strong>céphalées rebelles</strong>, des <strong>phosphènes</strong>, des <strong>acouphènes</strong>, des <strong>troubles visuels</strong> (« flash »), des <strong>ROT vifs et polycinétiques</strong>, une <strong>barre épigastrique</strong> et une <strong>ascension tensionnelle rapide</strong>.</li></ul>"},{"i":"3d1dda8ac16b","n":344,"o":"344-5","u":"Diagnostic","t":"Connaître les éléments du bilan clinique d'une pré-éclampsie","q":"Quels sont les critères cliniques maternels de sévérité d'une pré-éclampsie nécessitant une hospitalisation en milieu spécialisé ?","a":"<p>Les critères cliniques maternels de sévérité, dont la présence d'au moins un justifie une hospitalisation en milieu spécialisé, sont :</p><ul><li><strong>HTA sévère</strong> : pression artérielle systolique <strong>> 160 mmHg</strong> ou diastolique <strong>> 110 mmHg</strong>, ou HTA non contrôlée.</li><li><strong>Oligurie</strong> : diurèse <strong>< 500 mL/24 h</strong> ou <strong>≤ 25 mL/h</strong>.</li><li><strong>Barre épigastrique</strong>.</li><li><strong>Signes neurologiques persistants</strong> : <strong>céphalées</strong>, <strong>ROT vifs polycinétiques</strong>, <strong>troubles visuels</strong>.</li><li><strong>Œdème aigu du poumon (OAP)</strong>.</li><li><strong>Hématome rétroplacentaire (HRP)</strong> diagnostiqué ou suspecté.</li><li><strong>Convulsion</strong> ou <strong>troubles de la conscience</strong>.</li></ul>"},{"i":"df62afeaf50a","n":344,"o":"344-5","u":"Diagnostic","t":"Connaître les éléments du bilan clinique d'une pré-éclampsie","q":"Comment évaluer cliniquement l'état maternel face à une suspicion de pré-éclampsie ?","a":"<p>L'évaluation clinique maternelle comprend plusieurs axes :</p><ul><li>Surveillance des constantes : <strong>pression artérielle</strong>, <strong>fréquence cardiaque</strong>, <strong>fréquence respiratoire</strong>.</li><li>Examen neurologique : état de conscience, recherche de <strong>céphalées</strong>, <strong>troubles visuels</strong>, <strong>acouphènes</strong>, <strong>phosphènes</strong>, et des <strong>réflexes ostéotendineux vifs et polycinétiques</strong> (signes d'éclampsie).</li><li>Recherche des signes d'HELLP syndrome : <strong>douleur épigastrique</strong>, <strong>nausées</strong>, <strong>vomissements</strong>.</li><li>Recherche des signes d'Hématome Rétroplacentaire (HRP) : <strong>métrorragies noires</strong>, <strong>contracture utérine douloureuse permanente</strong>, signes de <strong>choc hémorragique</strong>.</li><li>Évaluation des <strong>œdèmes</strong> (face, membres supérieurs/inférieurs, ascite) et de la <strong>prise de poids</strong>.</li><li>Recherche d'un <strong>Œdème Aigu du Poumon (OAP)</strong> : détresse respiratoire, crépitants/sibilants.</li><li>Évaluation de la fonction rénale : quantification de la <strong>diurèse</strong> et bilan entrées-sorties.</li></ul>"},{"i":"f52c0d5510e8","n":344,"o":"344-5","u":"Diagnostic","t":"Connaître les éléments du bilan clinique d'une pré-éclampsie","q":"Comment évaluer cliniquement le retentissement fœtal lors d'une pré-éclampsie ?","a":"<p>L'évaluation clinique du retentissement fœtal comprend :</p><ul><li>La mesure de la <strong>hauteur utérine</strong> pour dépister une éventuelle <strong>Restriction de Croissance Intra-Utérine (RCIU)</strong>.</li><li>L'appréciation des <strong>mouvements actifs fœtaux</strong> pour évaluer la vitalité.</li><li>L'auscultation des <strong>bruits du cœur fœtal</strong>.</li></ul>"},{"i":"0d5f23a60a11","n":344,"o":"344-7","u":"Identifier une urgence","t":"Connaître les éléments d'anamnèse permettant d'identifier un retentissement fœtal de la pré-éclampsie","q":"Quel est le mécanisme principal du retentissement fœtal de la pré-éclampsie ?","a":"<p>Le retentissement fœtal de la pré-éclampsie traduit une <strong>insuffisance utéro-placentaire</strong>.</p>"},{"i":"1f6418a3ee47","n":344,"o":"344-7","u":"Identifier une urgence","t":"Connaître les éléments d'anamnèse permettant d'identifier un retentissement fœtal de la pré-éclampsie","q":"Quels sont les examens paracliniques clefs pour évaluer le retentissement fœtal et ses critères de gravité dans la pré-éclampsie ?","a":"<ul><li>Une <strong>échographie fœtale</strong> pour objectiver un RCIU sévère ou un oligoamnios.</li><li>Des <strong>dopplers fœtaux</strong> (artères ombilicales, cérébrales).</li><li>Un <strong>enregistrement du rythme cardiaque fœtal (RCF)</strong> pour identifier toute anomalie du RCF.</li></ul>"},{"i":"f570d9f590b8","n":344,"o":"344-7","u":"Identifier une urgence","t":"Connaître les éléments d'anamnèse permettant d'identifier un retentissement fœtal de la pré-éclampsie","q":"Quels sont les signes cliniques maternels à l'anamnèse pouvant faire suspecter un retentissement fœtal de la pré-éclampsie ?","a":"<ul><li>Une <strong>diminution des mouvements actifs fœtaux</strong> (perte de vitalité fœtale).</li><li>Une <strong>hauteur utérine inférieure à la normale</strong>, faisant suspecter un RCIU.</li></ul>"}]};